#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

struct Edge {
    int u, v;
    long long w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j, int new_root) {
        int root_i = find(i);
        int root_j = find(j);
        parent[root_i] = new_root;
        parent[root_j] = new_root;
        parent[new_root] = new_root;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    int total_cells = n * m;
    vector<long long> p(total_cells);

    auto get_id = [&](int r, int c) {
        return r * m + c;
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> p[get_id(i, j)];
        }
    }

    if (total_cells == 1) {
        cout << p[0] << "\n";
        return 0;
    }

    vector<Edge> edges;
    edges.reserve(2 * total_cells);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int u = get_id(i, j);
            if (i + 1 < n) {
                int v = get_id(i + 1, j);
                edges.push_back({u, v, max(p[u], p[v])});
            }
            if (j + 1 < m) {
                int v = get_id(i, j + 1);
                edges.push_back({u, v, max(p[u], p[v])});
            }
        }
    }

    sort(edges.begin(), edges.end());

    int max_nodes = 2 * total_cells;
    vector<long long> S(max_nodes, 0);
    vector<long long> W(max_nodes, 0);
    vector<vector<int>> children(max_nodes);

    for (int i = 0; i < total_cells; ++i) {
        S[i] = p[i];
    }

    DSU dsu(max_nodes);
    int curr_node = total_cells;

    for (const auto& edge : edges) {
        int root_u = dsu.find(edge.u);
        int root_v = dsu.find(edge.v);
        if (root_u != root_v) {
            int new_node = curr_node++;
            W[new_node] = edge.w;
            S[new_node] = S[root_u] + S[root_v];
            children[new_node].push_back(root_u);
            children[new_node].push_back(root_v);
            dsu.unite(root_u, root_v, new_node);
        }
    }

    int root = curr_node - 1;
    vector<long long> ans(max_nodes, 0);
    ans[root] = S[root];

    vector<int> stack_dfs;
    stack_dfs.push_back(root);

    while (!stack_dfs.empty()) {
        int u = stack_dfs.back();
        stack_dfs.pop_back();

        for (int v : children[u]) {
            if (S[v] >= W[u]) {
                ans[v] = ans[u];
            } else {
                ans[v] = S[v];
            }
            stack_dfs.push_back(v);
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int id = get_id(i, j);
            cout << ans[id] << (j == m - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
